// ReadOnlyMultiSelect.stories.js
import React, { useState } from 'react';
import { MultiSelect } from 'carbon-components-react';
import './_read-only.scss'; // make sure our CSS contains .bx--multi-select--readonly overrides

export default {
  title: 'MultiSelect/ReadOnly',
  component: MultiSelect,
  parameters: {
    docs: {
      description: {
        story: 'A read‐only version of the MultiSelect.  It shows chosen items as tags and prevents any changes.'
      }
    }
  },
  argTypes: {
    readOnly: { control: 'boolean' },
    items: { control: false },
    initialSelectedItems: { control: false },
  }
};

const allItems = [
  { id: 'option-1', text: 'Option 1' },
  { id: 'option-2', text: 'Option 2' },
  { id: 'option-3', text: 'Option 3' },
  { id: 'option-4', text: 'Option 4' },
];

const Template = ({ readOnly, ...rest }) => {
  // Use state only to reflect initialSelectedItems in Storybook controls
  const [selectedItems] = useState(rest.initialSelectedItems);

  // override onChange to do nothing in readOnly mode
  const handleChange = (data) => {
    if (!readOnly) {
      // normally call setState, but readOnly prevents changes
    }
  };

  return (
    <MultiSelect
      {...rest}
      className={readOnly ? 'bx--multi-select--readonly' : ''}
      items={allItems}
      onChange={handleChange}
      initialSelectedItems={selectedItems}
      itemToString={(item) => (item ? item.text : '')}
      readOnly={readOnly}
    />
  );
};

export const Readonly = Template.bind({});
Readonly.args = {
  label: 'Filters',
  placeholder: 'Choose options…',
  initialSelectedItems: [allItems[0], allItems[1]],
  readOnly: true,
};

// _read-only.scss
// This file should live alongside the story to override the default MultiSelect styles
// You will apply colors and tokens per the design spec images above.

.bx--multi-select--readonly {
  // Outer control
  .bx--list-box__field {
    background-color: transparent; /* transparent background */
    border-style: dashed;        /* match dotted border in spec */
    cursor: default;
  }
  .bx--list-box__menu-icon {
    fill: var(--cds-icon-disabled);
    pointer-events: none;
  }

  // Tags
  .bx--multi-select__selection .bx--tag {
    background-color: transparent;
    border-color: var(--cds-border-strong-01);
    color: var(--cds-text-secondary);
    .bx--tag__close-icon {
      fill: var(--cds-icon-disabled);
      cursor: default;
      pointer-events: none;
    }
  }
}
